function drift(seed: number, n = 24, base = 50, range = 30) {
  const arr: number[] = [];
  let s = seed;
  let v = base;
  for (let i = 0; i < n; i++) {
    s = (s * 9301 + 49297) % 233280;
    v += (s / 233280 - 0.5) * range * 0.5;
    v = Math.max(base - range, Math.min(base + range, v));
    arr.push(v);
  }
  return arr;
}

